INSERT INTO maintenance_requests (unit_id, tenant_id, title, description, category, priority, status, assigned_to, ai_classified, technician_notes) VALUES
  ('b1000000-0000-0000-0000-000000000005','c1000000-0000-0000-0000-000000000004','Air conditioning leaking','The AC unit in the living room is dripping water onto the floor. Started 2 days ago, getting worse.','hvac','urgent','in_progress','Mike Torres (HVAC Specialist)',TRUE,'Check drain line first — likely blockage. Bring condensate pump as backup.'),
  ('b1000000-0000-0000-0000-000000000002','c1000000-0000-0000-0000-000000000002','Kitchen tap dripping','The hot water tap in the kitchen drips constantly even when fully closed.','plumbing','medium','open',NULL,TRUE,'Replace tap washer or cartridge. Turn off water at unit valve before starting.'),
  ('b2000000-0000-0000-0000-000000000003','c2000000-0000-0000-0000-000000000003','Power outlet not working','The outlet near the TV wall in the living room has stopped working. Tried resetting the circuit breaker.','electrical','high','in_progress','Sarah Lee (Electrician)',TRUE,'Check GFCI outlet upstream. May need to replace outlet. Take photos before work.'),
  ('b1000000-0000-0000-0000-000000000007','c1000000-0000-0000-0000-000000000006','Dishwasher not draining','Dishwasher fills with water but does not drain at end of cycle. Water sitting in bottom.','appliance','medium','open',NULL,TRUE,NULL),
  ('b2000000-0000-0000-0000-000000000001','c2000000-0000-0000-0000-000000000001','Bathroom door hinge broken','The main bathroom door hinge is broken — door sags and will not close properly.','structural','low','resolved','General Maintenance',FALSE,'Replaced hinge. Door closing and locking correctly. Job complete.'),
  ('b1000000-0000-0000-0000-000000000009','c1000000-0000-0000-0000-000000000007','Hot water system cold','No hot water in the entire unit since this morning. Both kitchen and bathroom affected.','plumbing','urgent','open',NULL,TRUE,'Check hot water unit thermostat. If pilot light out, relight. If system failure, arrange emergency replacement.'),
  ('b2000000-0000-0000-0000-000000000005','c2000000-0000-0000-0000-000000000004','Window seal cracked','Bedroom window seal is cracked — can feel cold air coming in during windy days.','structural','low','open',NULL,FALSE,NULL),
  ('b1000000-0000-0000-0000-000000000001','c1000000-0000-0000-0000-000000000001','Stove element not heating','Middle burner on the electric stove does not heat up at all. Other burners fine.','appliance','medium','resolved','Appliance Tech',TRUE,'Replaced faulty heating element. Tested all burners — all working.')
